<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kayıt Ol</title><link rel="stylesheet" href="/assets/app.css"></head><body class="login-page"><main class="login-card"><div class="brand large"><span class="brand-mark">A</span><span>HESAP OLUŞTUR</span></div><p class="muted">Loader kütüphanesine erişmek için kayıt olun.</p><div id="message"></div><form id="register-form"><label>Görünen ad<input name="display_name" minlength="2" maxlength="100" required></label><label>E-posta<input name="email" type="email" required></label><label>Güçlü şifre<input name="password" type="password" minlength="12" required></label><button class="button primary wide">Kayıt Ol</button></form></main><script>document.querySelector("#register-form").onsubmit=async function(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const response=await fetch("/api/auth/register/",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});const json=await response.json();const message=document.querySelector("#message");message.className=response.ok?"alert":"alert error";message.textContent=response.ok?json.data.message:json.error.message;if(response.ok)event.target.reset()};</script></body></html>
